/* ============ QR STUDIO ============ */
var QR=load("qr",{type:"url",vals:{},fg:"#111827",bg:"#FFFFFF",style:"square",eye:"square",margin:4,ecl:"M",caption:"",logo:"",logoScale:0.2,dl:1024});
var qrLogoImg=null;
function qrType(){return QR_TYPES.filter(function(t){return t.id===QR.type;})[0]||QR_TYPES[0];}
function qrVals(){return QR.vals[QR.type]||(QR.vals[QR.type]={});}
function qrOpts(size){return {size:size,margin:+QR.margin,fg:QR.fg,bg:QR.bg,style:QR.style,eye:QR.eye,ecl:QR.ecl,caption:QR.caption,logo:qrLogoImg,logoData:QR.logo,logoScale:+QR.logoScale};}
VIEWS.qr={html:function(){
  return '<div class="head"><h1>QR code studio</h1><p class="muted">Choose what the code should do, fill in the details and style it. The preview is the exact code you download.</p></div>'+
  '<div class="tool"><div class="stack">'+
    '<div class="card"><h2>1. What should it open?</h2><div class="types" role="group" aria-label="QR type">'+QR_TYPES.map(function(t){return '<button class="type" data-qtype="'+t.id+'" aria-pressed="'+(QR.type===t.id)+'">'+esc(t.name)+'</button>';}).join("")+'</div></div>'+
    '<div class="card"><h2>2. Details</h2><div id="qr-fields" class="stack"></div></div>'+
    '<div class="card"><h2>3. Style</h2>'+
      '<div class="row"><label class="f">Code colour<input id="qr-fg" type="color" value="'+esc(QR.fg)+'"></label><label class="f">Background<input id="qr-bg" type="color" value="'+esc(QR.bg)+'"></label><button class="btn ghost sm" id="qr-swap" style="align-self:flex-end">Reset colours</button></div>'+
      '<label class="f">Dot shape</label><div class="seg" role="group" aria-label="Dot shape">'+[["square","Square"],["rounded","Rounded"],["dots","Dots"]].map(function(o){return '<button data-qstyle="'+o[0]+'" aria-pressed="'+(QR.style===o[0])+'">'+o[1]+'</button>';}).join("")+'</div>'+
      '<label class="f">Corner shape</label><div class="seg" role="group" aria-label="Corner shape">'+[["square","Square"],["rounded","Rounded"]].map(function(o){return '<button data-qeye="'+o[0]+'" aria-pressed="'+(QR.eye===o[0])+'">'+o[1]+'</button>';}).join("")+'</div>'+
      '<div class="grid2"><label class="f">Text under the code (optional)<input id="qr-caption" type="text" maxlength="40" value="'+esc(QR.caption)+'" placeholder="Scan to order"></label>'+
      '<label class="f">Border size<select id="qr-margin">'+[1,2,3,4,6].map(function(m){return '<option value="'+m+'"'+(+QR.margin===m?" selected":"")+'>'+m+(m===4?" (recommended)":"")+'</option>';}).join("")+'</select></label></div>'+
      '<label class="f">Damage resistance<span class="hint">Higher means the code still scans if it gets scratched or covered, but has more dots.</span><select id="qr-ecl">'+[["L","Low"],["M","Medium (recommended)"],["Q","High"],["H","Highest"]].map(function(o){return '<option value="'+o[0]+'"'+(QR.ecl===o[0]?" selected":"")+'>'+o[1]+'</option>';}).join("")+'</select></label>'+
      '<div class="stack"><div class="row between"><b class="small">Logo in the middle (optional)</b>'+(QR.logo?'<button class="btn ghost sm" id="qr-logo-clear">Remove logo</button>':'')+'</div>'+
        '<label class="btn ghost" for="qr-logo" style="align-self:flex-start">'+(QR.logo?"Change logo":"Upload logo")+'</label><input id="qr-logo" type="file" accept="image/*" hidden>'+
        (QR.logo?'<label class="f">Logo size<input id="qr-logoscale" type="range" min="0.12" max="0.24" step="0.02" value="'+QR.logoScale+'"></label><p class="small muted">With a logo the code uses the highest damage resistance automatically so it still scans.</p>':'')+'</div>'+
    '</div>'+
  '</div><div class="sticky"><div class="card"><h2>Your QR code</h2><div class="qrwrap"><canvas id="qr-canvas" width="1024" height="1024" aria-label="QR code preview"></canvas><div id="qr-msg" class="stack" style="width:100%"></div>'+
    '<div class="row" style="justify-content:center"><select id="qr-dl" aria-label="PNG size" style="width:auto">'+[512,1024,2048].map(function(s){return '<option value="'+s+'"'+(+QR.dl===s?" selected":"")+'>'+s+' px</option>';}).join("")+'</select><button class="btn" id="qr-png">Download PNG</button><button class="btn ghost" id="qr-svg">Download SVG</button></div>'+
    '<details style="width:100%"><summary class="small muted">What is inside this code</summary><div id="qr-payload" class="payload"></div><button class="btn ghost sm" id="qr-copy" style="margin-top:8px">Copy content</button></details>'+
  '</div></div></div></div>';
},mount:function(){
  qrFields();
  if(QR.logo&&!qrLogoImg){var im=new Image();im.onload=function(){qrLogoImg=im;qrUpdate();};im.src=QR.logo;}
  qrUpdate();
}};
function qrFields(){
  var t=qrType(),v=qrVals(),html="",half=[];
  function flush(){if(half.length){html+='<div class="grid2">'+half.join("")+'</div>';half=[];}}
  t.fields.forEach(function(f){if(f.show&&(v.mode||"address")!==f.show)return;var h=field(f,v[f.k],"qf-");if(f.half||f.t==="tel")half.push(h);else{flush();html+=h;}});flush();
  $("qr-fields").innerHTML=html;
}
var qrPayload="";
function qrUpdate(){
  var t=qrType(),v=qrVals();t.fields.forEach(function(f){if(v[f.k]==null&&f.d!=null)v[f.k]=f.d;});
  var b=t.build(v),cv=$("qr-canvas"),msg=$("qr-msg");if(!cv)return;
  var w=qrWarnings(qrOpts(1024));qrPayload="";
  if(b.err){var ctx=cv.getContext("2d");cv.width=1024;cv.height=1024;ctx.fillStyle="#F1F3F8";ctx.fillRect(0,0,1024,1024);ctx.fillStyle="#7A8396";ctx.font="600 40px Inter, Arial, sans-serif";ctx.textAlign="center";ctx.fillText("Fill in the details",512,500);ctx.font="400 30px Inter, Arial, sans-serif";ctx.fillText("Your QR code appears here",512,556);
    msg.innerHTML='<div class="note info">'+esc(b.err)+'</div>';setDl(false);$("qr-payload").textContent="";store("qr",QR);return;}
  try{drawQR(cv,b.data,qrOpts(1024));qrPayload=b.data;
    msg.innerHTML=w.map(function(x){return '<div class="note warn">'+esc(x)+'</div>';}).join("")+(w.length?"":'<div class="note ok">Ready to scan. Test it with your phone camera before printing.</div>');setDl(true);}
  catch(e){msg.innerHTML='<div class="note bad">'+esc(e.message)+'</div>';setDl(false);}
  $("qr-payload").textContent=qrPayload;store("qr",QR);
}
function setDl(on){["qr-png","qr-svg","qr-copy"].forEach(function(id){var b=$(id);if(b)b.disabled=!on;});}
