function dayBtns(days,attr){return ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"].map(function(d,i){return '<button class="btn sm '+(days.indexOf(i)>=0?"soft":"ghost")+'" '+attr+'="'+i+'" aria-pressed="'+(days.indexOf(i)>=0)+'">'+d+'</button>';}).join("");}
function botBuildHTML(){
  var b=BOT;
  return '<div class="card"><h2>Business</h2><div class="grid2"><label class="f">Business name<input id="b-business" data-b="business" type="text" value="'+esc(b.business)+'"></label>'+
    '<label class="f">Time zone<select id="b-tz" data-b="tz">'+TZS.map(function(z){return '<option'+(b.tz===z?" selected":"")+'>'+z+'</option>';}).join("")+'</select></label></div>'+
    '<div class="grid2"><label class="f">Opens<input id="b-open" data-bh="open" type="time" value="'+esc(b.hours.open)+'"></label><label class="f">Closes<input id="b-close" data-bh="close" type="time" value="'+esc(b.hours.close)+'"></label></div>'+
    '<div><div class="small" style="font-weight:600;margin-bottom:6px">Open on</div><div class="row">'+dayBtns(b.hours.days,"data-bday")+'</div></div>'+
    '<p class="small muted">In any reply you can write <span class="kbd">{business}</span>, <span class="kbd">{hours}</span> or <span class="kbd">{menu}</span> and the bot fills it in.</p></div>'+
  '<div class="card"><h2>Welcome message</h2><p class="small muted">Sent when someone says hi, salam or hello. Your numbered menu is added below it.</p><textarea id="b-welcome" data-b="welcome">'+esc(b.welcome)+'</textarea></div>'+
  '<div class="card"><div class="row between"><h2>Numbered menu</h2><button class="btn soft sm" id="b-addopt">Add option</button></div><p class="small muted">Customers reply with a number. Typing the option name works too.</p><div id="b-opts" class="stack">'+
    b.options.map(function(o,i){return '<div class="list-item"><div class="stack"><label class="f">Option '+(i+1)+'<input id="bo-t-'+i+'" data-bo="title" data-i="'+i+'" type="text" value="'+esc(o.title)+'"></label><label class="f">Reply<textarea id="bo-r-'+i+'" data-bo="reply" data-i="'+i+'">'+esc(o.reply)+'</textarea></label></div><button class="x" data-bodel="'+i+'" aria-label="Remove option '+(i+1)+'">×</button></div>';}).join("")+'</div></div>'+
  '<div class="card"><div class="row between"><h2>Keyword replies</h2><button class="btn soft sm" id="b-addrule">Add keyword reply</button></div><p class="small muted">If a message contains any of the words, this reply is sent. Separate words with commas. Roman Urdu works too.</p><div class="stack">'+
    b.rules.map(function(r,i){return '<div class="list-item"><div class="stack"><label class="f">When the message has<input id="br-k-'+i+'" data-br="keywords" data-i="'+i+'" type="text" value="'+esc(r.keywords)+'"></label><label class="f">Reply<textarea id="br-r-'+i+'" data-br="reply" data-i="'+i+'">'+esc(r.reply)+'</textarea></label></div><button class="x" data-brdel="'+i+'" aria-label="Remove keyword reply">×</button></div>';}).join("")+'</div></div>'+
  '<div class="card"><h2>Hand over to a person</h2><label class="f">Words that ask for a person<input id="b-hk" data-bhand="keywords" type="text" value="'+esc(b.handoff.keywords)+'"></label><label class="f">Reply<textarea id="b-hr" data-bhand="reply">'+esc(b.handoff.reply)+'</textarea></label></div>'+
  '<div class="card"><h2>When the bot does not understand</h2><textarea id="b-fallback" data-b="fallback">'+esc(b.fallback)+'</textarea></div>'+
  '<div class="card"><h2>Closed hours</h2><label class="check"><input id="b-away" type="checkbox"'+(b.away.enabled?" checked":"")+'>Send a closed message outside opening hours</label><textarea id="b-awaymsg" data-baway="message">'+esc(b.away.message)+'</textarea><p class="small muted">Menu answers and keyword replies still work when you are closed.</p></div>'+
  '<div class="card flat"><div class="row"><button class="btn ghost sm" id="b-export">Save bot file</button><label class="btn ghost sm" for="b-import">Open bot file</label><input id="b-import" type="file" accept=".json,application/json" hidden><button class="btn ghost sm" id="b-reset">Start from the example</button></div></div>';
}
function botAppPack(){
  var hours=botEngine(BOT,"",new Date(),true);/* warm */
  var menu=(BOT.options||[]).filter(function(o){return String(o.title||"").trim();});
  var welcome=botEngine(BOT,"hi",new Date(),true).replies[0]||"";
  var away=BOT.away.enabled?botEngine(BOT,"hi",new Date(),false).replies[0]||"":"";
  var quick=menu.map(function(o,i){return {sc:"/"+(i+1),title:o.title,text:botEngine(BOT,String(i+1),new Date(),true).replies[0]||""};});
  (BOT.rules||[]).forEach(function(r){var first=String(r.keywords||"").split(",")[0].trim().toLowerCase().replace(/[^a-z0-9]+/g,"");if(!first)return;quick.push({sc:"/"+first.slice(0,14),title:"Keyword: "+r.keywords,text:botEngine(BOT,String(r.keywords).split(",")[0],new Date(),true).replies[0]||""});});
  return {welcome:welcome,away:away,quick:quick};
}
function botAppHTML(){
  var p=botAppPack();
  function block(title,how,text,id){return '<div class="card"><h3>'+esc(title)+'</h3><p class="small muted">'+how+'</p><div class="out" id="'+id+'">'+esc(text)+'</div><button class="btn ghost sm" data-copyid="'+id+'" style="align-self:flex-start">Copy</button></div>';}
  return '<div class="card"><h2>Set up free in the WhatsApp Business app</h2><div class="note ok">Costs nothing and needs no code. Install the free WhatsApp Business app on your phone, then paste the messages below.</div>'+
    '<ol class="steps small"><li>Open WhatsApp Business, tap the three dots or Settings, then <b>Business tools</b>.</li><li>Open <b>Greeting message</b>, turn it on and paste the greeting below.</li><li>Open <b>Away message</b>, turn it on, choose <b>Outside of business hours</b> and paste the away message.</li><li>Open <b>Quick replies</b> and add each one with its shortcut. In any chat, type <span class="kbd">/</span> to send one with a tap.</li></ol>'+
    '<div class="note warn">What the free app can and cannot do: it sends the greeting and away messages automatically, but it cannot read a number and answer by itself. You send menu answers with one tap using quick replies. For fully automatic answers use the full bot (step 2b).</div></div>'+
    block("Greeting message","Business tools, Greeting message.",p.welcome,"ap-greet")+
    (p.away?block("Away message","Business tools, Away message, Outside of business hours.",p.away,"ap-away"):"")+
    p.quick.map(function(q,i){return block("Quick reply "+q.sc+" · "+q.title,"Business tools, Quick replies, add. Shortcut: "+esc(q.sc),q.text,"ap-q"+i);}).join("");
}
function botWorkerCode(){
  var cfg=JSON.parse(JSON.stringify(BOT));
  var L=[];
  L.push("// WhatsApp auto-reply bot made with FreeToolBuilder.");
  L.push("// Runs on the free plan of Cloudflare Workers and the WhatsApp Cloud API from Meta.");
  L.push("// Needed settings (Cloudflare: your Worker, Settings, Variables and Secrets):");
  L.push("//   VERIFY_TOKEN   any secret word you choose; type the same word in Meta's webhook setup");
  L.push("//   WHATSAPP_TOKEN the access token from your Meta app (WhatsApp, API Setup)");
  L.push("//   APP_SECRET     optional but recommended: Meta app, App settings, Basic, App secret");
  L.push("");
  L.push("const CONFIG = "+JSON.stringify(cfg,null,2)+";");
  L.push("const GRAPH = \"https://graph.facebook.com/\" + (CONFIG.apiVersion || \"v23.0\");");
  L.push("");
  L.push(botEngine.toString());
  L.push("");
  L.push("const recent = new Map();");
  L.push("function hex(buf){return [...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,\"0\")).join(\"\");}");
  L.push("async function signatureOk(header, raw, secret){");
  L.push("  if(!header || !header.startsWith(\"sha256=\")) return false;");
  L.push("  const key = await crypto.subtle.importKey(\"raw\", new TextEncoder().encode(secret), {name:\"HMAC\", hash:\"SHA-256\"}, false, [\"sign\"]);");
  L.push("  const sig = hex(await crypto.subtle.sign(\"HMAC\", key, new TextEncoder().encode(raw)));");
  L.push("  const got = header.slice(7);");
  L.push("  if(got.length !== sig.length) return false;");
  L.push("  let diff = 0; for(let i=0;i<sig.length;i++) diff |= sig.charCodeAt(i) ^ got.charCodeAt(i);");
  L.push("  return diff === 0;");
  L.push("}");
  L.push("async function sendText(env, phoneNumberId, to, body){");
  L.push("  const res = await fetch(GRAPH + \"/\" + phoneNumberId + \"/messages\", {");
  L.push("    method: \"POST\",");
  L.push("    headers: {\"Authorization\": \"Bearer \" + env.WHATSAPP_TOKEN, \"Content-Type\": \"application/json\"},");
  L.push("    body: JSON.stringify({messaging_product:\"whatsapp\", recipient_type:\"individual\", to, type:\"text\", text:{preview_url:true, body}})");
  L.push("  });");
  L.push("  if(!res.ok) console.log(\"WhatsApp send failed\", res.status, await res.text());");
  L.push("}");
  L.push("function messageText(m){");
  L.push("  if(m.type === \"text\") return (m.text && m.text.body) || \"\";");
  L.push("  if(m.type === \"button\") return (m.button && m.button.text) || \"\";");
  L.push("  if(m.type === \"interactive\"){ const i = m.interactive || {}; return (i.button_reply && i.button_reply.title) || (i.list_reply && i.list_reply.title) || \"\"; }");
  L.push("  return \"\";");
  L.push("}");
  L.push("async function handle(env, body){");
  L.push("  for(const entry of body.entry || []) for(const change of entry.changes || []){");
  L.push("    const v = change.value || {}; const pid = v.metadata && v.metadata.phone_number_id;");
  L.push("    for(const m of v.messages || []){");
  L.push("      if(!pid || !m.from) continue;");
  L.push("      const res = botEngine(CONFIG, messageText(m), new Date());");
  L.push("      if(res.kind === \"fallback\" || res.kind === \"away\" || res.kind === \"handoff\"){");
  L.push("        const key = m.from + \":\" + res.kind, last = recent.get(key);");
  L.push("        if(last && Date.now() - last < 60 * 60 * 1000) continue; // do not repeat the same notice within an hour");
  L.push("        recent.set(key, Date.now());");
  L.push("      }");
  L.push("      for(const reply of res.replies) await sendText(env, pid, m.from, reply);");
  L.push("    }");
  L.push("  }");
  L.push("}");
  L.push("export default {");
  L.push("  async fetch(request, env, ctx){");
  L.push("    const url = new URL(request.url);");
  L.push("    if(request.method === \"GET\"){");
  L.push("      if(url.searchParams.get(\"hub.mode\") === \"subscribe\"){");
  L.push("        if(env.VERIFY_TOKEN && url.searchParams.get(\"hub.verify_token\") === env.VERIFY_TOKEN) return new Response(url.searchParams.get(\"hub.challenge\") || \"\", {status:200});");
  L.push("        return new Response(\"Verify token does not match\", {status:403});");
  L.push("      }");
  L.push("      return new Response(\"Your WhatsApp bot is running.\", {status:200});");
  L.push("    }");
  L.push("    if(request.method !== \"POST\") return new Response(\"Method not allowed\", {status:405});");
  L.push("    const raw = await request.text();");
  L.push("    if(env.APP_SECRET && !(await signatureOk(request.headers.get(\"x-hub-signature-256\"), raw, env.APP_SECRET))) return new Response(\"Bad signature\", {status:401});");
  L.push("    let body; try { body = JSON.parse(raw); } catch(e) { return new Response(\"Bad request\", {status:400}); }");
  L.push("    const job = handle(env, body).catch(e => console.log(\"Bot error\", String(e)));");
  L.push("    if(ctx && ctx.waitUntil) ctx.waitUntil(job); else await job;");
  L.push("    return new Response(\"OK\", {status:200});");
  L.push("  }");
  L.push("};");
  return L.join("\n");
}
function botApiHTML(){
  return '<div class="card"><h2>Full automatic bot</h2><div class="note info">This bot answers every message by itself, 24 hours a day, using exactly the replies you tested in the chat. The hosting is free on Cloudflare Workers. Replies to customers who message you first were free until 2026. Several WhatsApp providers report that from 1 October 2026 each business number gets 1,000 free replies a month, and Meta charges a small fee per reply after that. Check the current price in your Meta account before you go live.</div>'+
  '<ol class="steps small">'+
    '<li>Go to <b>developers.facebook.com</b>, create an app of type <b>Business</b> and add the <b>WhatsApp</b> product. Meta gives you a free test number to start with.</li>'+
    '<li>In WhatsApp, <b>API Setup</b>, copy the <b>access token</b>. For a permanent token, create a System User in Meta Business Settings and give it WhatsApp permissions.</li>'+
    '<li>Create a free account at <b>dash.cloudflare.com</b>, open <b>Workers and Pages</b>, create a Worker, choose <b>Edit code</b>, paste the code below and deploy.</li>'+
    '<li>In the Worker, open <b>Settings, Variables and Secrets</b> and add <span class="kbd">VERIFY_TOKEN</span> (any secret word), <span class="kbd">WHATSAPP_TOKEN</span> (the access token) and <span class="kbd">APP_SECRET</span> (Meta app, App settings, Basic).</li>'+
    '<li>Back in Meta, open WhatsApp, <b>Configuration</b>, Webhook, <b>Edit</b>. Paste your Worker address as the Callback URL and your secret word as the Verify token. Then subscribe to <b>messages</b>.</li>'+
    '<li>Send "hi" to your WhatsApp number from another phone. The bot replies within seconds.</li></ol>'+
  '<label class="f">WhatsApp API version<span class="hint">Leave this unless Meta tells you a version is retired.</span><input id="b-apiv" type="text" value="'+esc(BOT.apiVersion||"v23.0")+'"></label>'+
  '<div class="row"><button class="btn" id="b-copycode">Copy bot code</button><button class="btn ghost" id="b-dlcode">Download bot code</button></div>'+
  '<div class="code" id="b-code">'+esc(botWorkerCode())+'</div>'+
  '<p class="small muted">The code includes your replies. When you change them, copy the code again and paste it over the old one in Cloudflare.</p></div>'+
  '<div class="card"><h3>Good to know</h3><ul class="steps small"><li>To use your existing business number, Meta lets the WhatsApp Business app and the bot share one number in many countries (called coexistence). Check that it is offered for your number in Meta\'s setup screens.</li><li>The bot replies only to messages customers send you. Sending first to customers needs approved templates and is charged by Meta.</li><li>The bot does not repeat the same "closed" or "did not understand" message to one person within an hour.</li></ul></div>';
}
function botNow(){return botSim.mode==="open"?true:botSim.mode==="closed"?false:undefined;}
function botRenderMsgs(){
  var el=$("bot-msgs");if(!el)return;
  if(!botSim.log.length){el.innerHTML='<div class="bub sys">Say "hi" to start. Try a number, "price", "jazzcash" or "agent".</div>';return;}
  el.innerHTML=botSim.log.map(function(m){return '<div class="bub '+(m.who==="me"?"out":m.who==="sys"?"sys":"in")+'">'+esc(m.text)+(m.tag?'<span class="meta">'+esc(m.tag)+'</span>':'')+'</div>';}).join("");
  el.scrollTop=el.scrollHeight;
}
var KIND_LABEL={welcome:"Welcome",menu:"Menu",option:"Menu option",rule:"Keyword reply",handoff:"Hand over",away:"Closed message",fallback:"Did not understand"};
function botSend(text){
  botSim.log.push({who:"me",text:text});
  var r=botEngine(BOT,text,new Date(),botNow());
  if(r.replies.length)r.replies.forEach(function(x){botSim.log.push({who:"bot",text:x,tag:KIND_LABEL[r.kind]||r.kind});});
  else botSim.log.push({who:"sys",text:"No reply. Add a fallback message so the bot always answers."});
  botRenderMsgs();
}
function botSave(){store("bot",BOT);botHeader();}

