VIEWS.voice={html:function(){
  return '<div class="head"><h1>Voice agent builder</h1><p class="muted">Design a phone agent that greets callers, answers common questions, takes bookings and hands over to a person. Talk to it here, then copy the ready prompt into a voice agent platform.</p></div>'+
  '<div class="seg" role="group" aria-label="Voice steps" style="max-width:520px">'+[["build","1. Design"],["export","2. Put it on a phone line"]].map(function(o){return '<button data-vtab="'+o[0]+'" aria-pressed="'+(voiceTab===o[0])+'">'+o[1]+'</button>';}).join("")+'</div>'+
  '<button class="btn soft sm jump" data-jump="v-chat">Go to the test call</button><div class="tool"><div class="stack" id="v-left"></div><div class="sticky" id="v-chat"><div class="phone"><div class="phone-top"><span class="avatar">'+ic("voice",18)+'</span><div style="min-width:0"><b id="v-nm"></b><div class="small muted" id="v-status">Test call</div></div></div>'+
  '<div class="msgs" id="v-msgs" aria-live="polite"></div><form class="composer" id="v-form"><button type="button" class="btn ghost mic" id="v-mic" aria-label="Speak" hidden>'+ic("voice",16)+'</button><input id="v-in" type="text" placeholder="Say or type what a caller says" autocomplete="off" aria-label="Caller says"><button class="btn" type="submit">Send</button></form></div>'+
  '<div class="row" style="margin-top:10px"><button class="btn" id="v-start">Start test call</button><label class="check small"><input id="v-speak" type="checkbox"'+(vSim.speak?" checked":"")+'>Speak replies aloud</label></div></div></div>';
},mount:function(){vLeft();$("v-nm").textContent=VOICE.agent+" · "+VOICE.business;vRender();vSetupMic();},leave:function(){vStopAudio();}};
