function vBuildHTML(){
  var v=VOICE;
  return '<div class="card"><h2>Agent</h2><div class="grid2"><label class="f">Agent name<input id="v-agent" data-v="agent" type="text" value="'+esc(v.agent)+'"></label><label class="f">Business<input id="v-business" data-v="business" type="text" value="'+esc(v.business)+'"></label></div>'+
    '<label class="f">What the agent is for<input id="v-purpose" data-v="purpose" type="text" value="'+esc(v.purpose)+'"></label>'+
    '<div class="grid2"><label class="f">Language<select id="v-lang" data-v="lang">'+[["en","English"],["ur","Urdu"],["both","English and Urdu (answer in the caller\'s language)"]].map(function(o){return '<option value="'+o[0]+'"'+(v.lang===o[0]?" selected":"")+'>'+o[1]+'</option>';}).join("")+'</select></label><label class="f">Tone<input id="v-tone" data-v="tone" type="text" value="'+esc(v.tone)+'"></label></div>'+
    '<label class="f">First thing it says<textarea id="v-greeting" data-v="greeting">'+esc(v.greeting)+'</textarea></label></div>'+
  '<div class="card"><div class="row between"><h2>Questions it can answer</h2><button class="btn soft sm" id="v-addfaq">Add answer</button></div><div class="stack">'+
    v.faqs.map(function(f,i){return '<div class="list-item"><div class="stack"><label class="f">When the caller mentions<input id="vf-k-'+i+'" data-vf="keywords" data-i="'+i+'" type="text" value="'+esc(f.keywords)+'"></label><label class="f">The agent says<textarea id="vf-a-'+i+'" data-vf="answer" data-i="'+i+'">'+esc(f.answer)+'</textarea></label></div><button class="x" data-vfdel="'+i+'" aria-label="Remove answer">×</button></div>';}).join("")+'</div></div>'+
  '<div class="card"><h2>Bookings</h2><label class="check"><input id="v-bookon" type="checkbox"'+(v.bookingOn?" checked":"")+'>Take bookings or appointments</label>'+
    '<label class="f">Words that start a booking<input id="v-bookwords" data-v="bookingWords" type="text" value="'+esc(v.bookingWords)+'"></label>'+
    '<label class="f">Details to collect<span class="hint">One per line: Name | the question the agent asks</span><textarea id="v-fields" data-v="fieldsText">'+esc(v.fieldsText)+'</textarea></label>'+
    '<label class="f">After the booking it says<textarea id="v-bookdone" data-v="bookingDone">'+esc(v.bookingDone)+'</textarea></label></div>'+
  '<div class="card"><h2>Handing over and ending</h2><label class="f">Words that ask for a person<input id="v-tw" data-v="transferWords" type="text" value="'+esc(v.transferWords)+'"></label>'+
    '<div class="grid2"><label class="f">It says before transferring<input id="v-tm" data-v="transferMsg" type="text" value="'+esc(v.transferMsg)+'"></label><label class="f">Transfer to number (optional)<input id="v-tn" data-v="transferNumber" type="tel" value="'+esc(v.transferNumber)+'" placeholder="+92 42 1234567"></label></div>'+
    '<label class="f">When it does not know<textarea id="v-fb" data-v="fallback">'+esc(v.fallback)+'</textarea></label><label class="f">Goodbye line<input id="v-close" data-v="closing" type="text" value="'+esc(v.closing)+'"></label></div>'+
  '<div class="card flat"><div class="row"><button class="btn ghost sm" id="v-export">Save agent file</button><label class="btn ghost sm" for="v-import">Open agent file</label><input id="v-import" type="file" accept=".json,application/json" hidden><button class="btn ghost sm" id="v-reset">Start from the example</button></div></div>';
}
function vPrompt(){
  var v=VOICE,f=parseFields(v.fieldsText),L=[];
  var lang=v.lang==="ur"?"Speak in Urdu.":v.lang==="both"?"Reply in the same language the caller uses, English or Urdu.":"Speak in English.";
  L.push("# Role");L.push("You are "+v.agent+", the phone assistant for "+v.business+". "+v.purpose);L.push("");
  L.push("# Style");L.push("- "+v.tone);L.push("- "+lang);L.push("- This is a phone call. Keep each reply to one or two sentences and ask one question at a time.");L.push("- Never invent prices, times or facts. Use only the information below.");L.push("");
  L.push("# Information you can share");v.faqs.forEach(function(q){if(String(q.answer).trim())L.push("- About "+String(q.keywords).split(",")[0].trim()+": "+vFill(q.answer));});L.push("");
  if(v.bookingOn&&f.length){L.push("# Taking a booking");L.push("When the caller wants to "+String(v.bookingWords).split(",").slice(0,3).join(", ")+", collect these details one at a time:");f.forEach(function(x,i){L.push((i+1)+". "+x.label+": ask \""+x.ask+"\"");});
    L.push("Then repeat all the details back to confirm, and say: \""+vFill(v.bookingDone)+"\"");L.push("If the caller says cancel, stop and ask if there is anything else.");L.push("");}
  L.push("# Handing over");L.push("If the caller asks for a "+String(v.transferWords).split(",").slice(0,4).map(function(s){return s.trim();}).join(", ")+", say: \""+vFill(v.transferMsg)+"\""+(v.transferNumber?" and transfer the call to "+v.transferNumber+".":" and end your turn so staff can call back."));L.push("");
  L.push("# When you do not know");L.push("Say: \""+vFill(v.fallback)+"\"");L.push("");
  L.push("# Ending the call");L.push("When the caller is done, say: \""+vFill(v.closing)+"\" and end the call.");
  return L.join("\n");
}
function vExportHTML(){
  var cfg={name:VOICE.agent+" ("+VOICE.business+")",firstMessage:vFill(VOICE.greeting),systemPrompt:vPrompt(),language:VOICE.lang,transferNumber:VOICE.transferNumber||null,collect:parseFields(VOICE.fieldsText).map(function(f){return {name:f.key,label:f.label,question:f.ask};})};
  return '<div class="card"><h2>Put your agent on a phone line</h2><p class="small muted">Voice platforms turn this prompt into a real agent that answers calls with a natural voice. Create a free account on one, paste the first message and the prompt, then test it in their web call before you connect a number.</p>'+
    '<ol class="steps small"><li>Pick a platform, for example <b>Vapi</b>, <b>Retell AI</b> or <b>ElevenLabs Agents</b>. They usually give free trial credits. A real phone number normally costs a small monthly fee, so check their current prices.</li>'+
    '<li>Create a new assistant or agent.</li><li>Paste the <b>First message</b> and the <b>Prompt</b> below into the matching boxes.</li><li>If you set a transfer number, add a transfer or forward step with that number in the platform.</li><li>Try it with the platform\'s test call, then buy or connect a phone number.</li></ol></div>'+
    '<div class="card"><h3>First message</h3><div class="out" id="v-o-first">'+esc(vFill(VOICE.greeting))+'</div><button class="btn ghost sm" data-copyid="v-o-first" style="align-self:flex-start">Copy</button></div>'+
    '<div class="card"><h3>Prompt (system instructions)</h3><div class="out" id="v-o-prompt">'+esc(vPrompt())+'</div><div class="row"><button class="btn sm" data-copyid="v-o-prompt">Copy prompt</button><button class="btn ghost sm" id="v-dlprompt">Download as text</button></div></div>'+
    '<div class="card"><h3>Settings file</h3><p class="small muted">All the settings in one file, for developers or for keeping a copy.</p><div class="code" id="v-o-json">'+esc(JSON.stringify(cfg,null,2))+'</div><div class="row"><button class="btn ghost sm" data-copyid="v-o-json">Copy</button><button class="btn ghost sm" id="v-dljson">Download JSON</button></div></div>';
}
function vRender(){
  var el=$("v-msgs");if(!el)return;
  if(!vSim.log.length){el.innerHTML='<div class="bub sys">Press Start test call. Then try "what are your timings", "book an appointment" or "can I talk to a person".</div>';return;}
  el.innerHTML=vSim.log.map(function(m){return '<div class="bub '+(m.who==="me"?"out":m.who==="sys"?"sys":"in")+'">'+esc(m.text)+'</div>';}).join("");el.scrollTop=el.scrollHeight;
}
var vTTS=null,vDict=null,vRec=null,vListening=false;
function vStopAudio(){try{if(vTTS)vTTS.stop();}catch(e){}try{if(window.speechSynthesis)speechSynthesis.cancel();}catch(e){}try{if(vRec)vRec.abort();}catch(e){}try{if(vDict&&vListening)vDict.stop();}catch(e){}vListening=false;}
function vSpeak(text){
  if(!vSim.speak||!text)return;
  var lang=VOICE.lang==="ur"?"ur-PK":"en-US";
  if(IN_ARTIFACT){(vTTS?Promise.resolve(vTTS):window.claude.use("tts")).then(function(t){vTTS=t;if(t)return t.speak(text).catch(function(){});}).catch(function(){});return;}
  try{if(!window.speechSynthesis)return;speechSynthesis.cancel();var u=new SpeechSynthesisUtterance(text);u.lang=lang;u.rate=1;speechSynthesis.speak(u);}catch(e){}
}
function vSay(text){vSim.log.push({who:"agent",text:text});vRender();vSpeak(text);}
function vCaller(text){
  if(!vSim.started){vStart();}
  vSim.log.push({who:"me",text:text});
  var r=voiceEngine(vCfg(),vSim.state,text);vSim.state=r.state;
  if(r.reply)vSay(r.reply);
  if(r.kind==="transfer"){vSim.log.push({who:"sys",text:VOICE.transferNumber?"Call transferred to "+VOICE.transferNumber:"Call handed to staff"});vRender();}
  if(r.kind==="end"||r.kind==="ended"){vSim.log.push({who:"sys",text:"Call ended"});vSim.started=false;vRender();$("v-start").textContent="Start test call";}
  if(r.kind==="booked"){vSim.log.push({who:"sys",text:"Booking captured: "+Object.keys(r.booking).map(function(k){return k+" = "+r.booking[k];}).join(", ")});vRender();}
}
function vStart(){vStopAudio();vSim={state:null,log:[],speak:vSim.speak,started:true};$("v-start").textContent="Restart call";vSay(vFill(VOICE.greeting));}
function vSetupMic(){
  var btn=$("v-mic");if(!btn)return;
  if(IN_ARTIFACT){window.claude.use("dictation").then(function(d){if(!d)return;vDict=d;btn.hidden=false;
    d.onFinal(function(e){if(e&&e.text&&e.text.trim()){$("v-in").value="";vCaller(e.text.trim());}});
    d.onPartial(function(e){$("v-in").value=e&&e.text||"";});
    d.onState(function(e){vListening=e.state==="listening"||e.state==="starting";btn.classList.toggle("on",vListening);$("v-status").textContent=vListening?"Listening...":"Test call";});}).catch(function(){});return;}
  var SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return;btn.hidden=false;
}
function vMicClick(){
  var btn=$("v-mic");
  if(IN_ARTIFACT&&vDict){if(vListening){vDict.stop().catch(function(){});return;}if(!vSim.started)vStart();vDict.start({language:VOICE.lang==="ur"?"ur-PK":"en-US"}).catch(function(e){toast(e&&e.code==="not_granted"?"Microphone is off for this page. You can type instead.":"Could not start the microphone. You can type instead.");});return;}
  var SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return;
  if(vListening&&vRec){vRec.stop();return;}
  if(!vSim.started)vStart();
  try{if(window.speechSynthesis)speechSynthesis.cancel();}catch(e){}
  vRec=new SR();vRec.lang=VOICE.lang==="ur"?"ur-PK":"en-US";vRec.interimResults=true;vRec.maxAlternatives=1;
  vRec.onresult=function(e){var txt="",fin=false;for(var i=e.resultIndex;i<e.results.length;i++){txt+=e.results[i][0].transcript;if(e.results[i].isFinal)fin=true;}$("v-in").value=txt;if(fin){$("v-in").value="";vCaller(txt.trim());}};
  vRec.onerror=function(e){toast(e.error==="not-allowed"?"Microphone permission was blocked. You can type instead.":"Did not catch that. Try again or type.");};
  vRec.onend=function(){vListening=false;btn.classList.remove("on");$("v-status").textContent="Test call";};
  vRec.start();vListening=true;btn.classList.add("on");$("v-status").textContent="Listening...";
}
function voiceSave(){store("voice",VOICE);var n=$("v-nm");if(n)n.textContent=VOICE.agent+" · "+VOICE.business;}

