var LINK=load("link",{phone:"",cc:"92",msg:"Hi! I would like to know more about your products."});
VIEWS.link={html:function(){
  return '<div class="head"><h1>WhatsApp link maker</h1><p class="muted">Anyone who taps the link opens a chat with you, with your message already typed. Put it in your Instagram bio, ads, emails or on a poster as a QR code.</p></div>'+
  '<div class="tool"><div class="card"><div class="grid2"><label class="f">Your WhatsApp number<input id="l-phone" data-l="phone" type="tel" inputmode="tel" value="'+esc(LINK.phone)+'" placeholder="0300 1234567"></label><label class="f">Country code<input id="l-cc" data-l="cc" type="text" inputmode="numeric" value="'+esc(LINK.cc)+'"></label></div>'+
    '<label class="f">Message the customer starts with<textarea id="l-msg" data-l="msg">'+esc(LINK.msg)+'</textarea></label><div id="l-err"></div>'+
    '<label class="f">Your link<div class="out" id="l-out"></div></label><div class="row"><button class="btn" id="l-copy">Copy link</button><a class="btn ghost" id="l-open" target="_blank" rel="noopener">Test the link</a></div></div>'+
  '<div class="sticky"><div class="card"><h2>QR code for this link</h2><div class="qrwrap"><canvas id="l-qr" width="512" height="512" aria-label="QR code for the link"></canvas><button class="btn ghost" id="l-png">Download PNG</button><p class="small muted">For colours and a logo, open this link in the <a href="#qr" id="l-toqr">QR code studio</a>.</p></div></div></div></div>';
},mount:function(){linkUpdate();}};
function linkUpdate(){
  var p=normPhone(LINK.phone,LINK.cc),ok=phoneOk(p),url=ok?waLink(p,LINK.msg):"";
  $("l-err").innerHTML=!LINK.phone?'<div class="note info">Enter your number. You can write it the local way, like 0300 1234567.</div>':!ok?'<div class="note bad">The number should be 8 to 15 digits including the country code.</div>':'<div class="note ok">Number used: +'+esc(p)+'</div>';
  $("l-out").textContent=url||"Your link appears here";
  ["l-copy","l-png"].forEach(function(id){$(id).disabled=!ok;});var o=$("l-open");if(ok){o.href=url;o.removeAttribute("aria-disabled");}else{o.removeAttribute("href");o.setAttribute("aria-disabled","true");}
  var cv=$("l-qr");if(ok)smallQR(cv,url);else{var c=cv.getContext("2d");cv.width=512;cv.height=512;c.fillStyle="#F1F3F8";c.fillRect(0,0,512,512);}
  store("link",LINK);return url;
}

