/* ============ BULK LINKS ============ */
var BULK=load("bulk",{cc:"92",msg:"Hi {name}, your order is ready for pickup. Thank you for shopping with us!",list:"Ali Khan, 0300 1234567\nSara Ahmed, 0321 7654321\nBilal, +971 50 123 4567"});
function bulkRows(){
  return String(BULK.list||"").split("\n").map(function(line,i){line=line.trim();if(!line)return null;var parts=line.split(/[,;\t]/).map(function(s){return s.trim();});
    var name="",num="";parts.forEach(function(p){if(digits(p).length>=7&&!num)num=p;else if(!name)name=p;});
    var n=normPhone(num,BULK.cc),ok=phoneOk(n),msg=String(BULK.msg||"").replace(/\{name\}/g,name||"there");
    return {line:i+1,name:name,raw:num,num:n,ok:ok,link:ok?waLink(n,msg):""};}).filter(Boolean);
}
VIEWS.bulk={html:function(){
  return '<div class="head"><h1>Bulk chat links</h1><p class="muted">Paste your customer list and a message. You get a personal WhatsApp link for each person, with their name filled in. Tap each link to send the message from your own phone.</p></div>'+
  '<div class="tool wide"><div class="card"><div class="grid2"><label class="f">Message<span class="hint">Write {name} where the customer\'s name should go.</span><textarea id="bk-msg" data-bk="msg">'+esc(BULK.msg)+'</textarea></label>'+
    '<label class="f">Customer list<span class="hint">One per line: name, number. You can paste from Excel.</span><textarea id="bk-list" data-bk="list" style="min-height:120px">'+esc(BULK.list)+'</textarea></label></div>'+
    '<div class="row"><label class="f" style="max-width:160px">Default country code<input id="bk-cc" data-bk="cc" type="text" inputmode="numeric" value="'+esc(BULK.cc)+'"></label></div>'+
    '<div id="bk-sum"></div><div class="tablewrap"><table><thead><tr><th>#</th><th>Name</th><th>Number</th><th>Link</th></tr></thead><tbody id="bk-rows"></tbody></table></div>'+
    '<div class="row"><button class="btn" id="bk-copy">Copy all links</button><button class="btn ghost" id="bk-csv">Download CSV</button></div>'+
    '<p class="small muted">To protect your number, send messages only to customers who know you, and space them out. WhatsApp can block numbers that send many unwanted messages.</p></div></div>';
},mount:function(){bulkUpdate();}};
function bulkUpdate(){
  var rows=bulkRows(),good=rows.filter(function(r){return r.ok;}).length;
  $("bk-rows").innerHTML=rows.length?rows.map(function(r,i){return '<tr><td class="num">'+(i+1)+'</td><td>'+esc(r.name||"-")+'</td><td class="num">'+(r.ok?"+"+esc(r.num):'<span class="err">Check number: '+esc(r.raw||"missing")+'</span>')+'</td><td>'+(r.ok?'<a href="'+esc(r.link)+'" target="_blank" rel="noopener">Open chat</a>':'')+'</td></tr>';}).join(""):'<tr><td colspan="4" class="muted">Paste your list above.</td></tr>';
  $("bk-sum").innerHTML=rows.length?'<div class="note '+(good===rows.length?"ok":"warn")+'">'+good+' of '+rows.length+' numbers are ready.'+(good<rows.length?" Fix the ones marked in red.":"")+'</div>':"";
  $("bk-copy").disabled=!good;$("bk-csv").disabled=!good;store("bulk",BULK);
}
function csvCell(s){s=String(s==null?"":s);return /[",\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;}

/* ============ FORMATTER ============ */
var TEMPLATES=[
  ["Order confirmed","*Order confirmed* ✅\n\nHi {name}, thank you for your order #{order}.\nTotal: *Rs {amount}*\nDelivery time: {time}\n\nWe will message you when it is on the way."],
  ["Payment reminder","Hi {name}, a gentle reminder that payment of *Rs {amount}* for invoice #{order} is due on {date}.\n\nYou can pay by {method}. Please send a screenshot after paying. Thank you!"],
  ["Appointment reminder","Hi {name}, this is a reminder of your appointment at *{business}* on *{date}* at *{time}*.\n\nReply *1* to confirm or *2* to reschedule."],
  ["Review request","Hi {name}, thank you for choosing {business}! 🙏\n\nIf you liked our service, could you leave us a quick review? It really helps:\n{link}"],
  ["New stock","*New arrivals are here!* 🛍️\n\n{item} is now in stock at *Rs {amount}*.\nReply _YES_ to reserve yours before it sells out."],
  ["Eid greeting","*Eid Mubarak!* 🌙\n\nFrom all of us at {business}, we wish you and your family a blessed Eid full of happiness."],
  ["Order ready (Roman Urdu)","Assalam o Alaikum {name}! Aap ka order #{order} tayyar hai. ✅\nTotal: *Rs {amount}*\n\nShukriya!"],
  ["Payment reminder (Roman Urdu)","Assalam o Alaikum {name}, invoice #{order} ki payment *Rs {amount}* {date} tak due hai. Payment ke baad screenshot zaroor bhejein. Shukriya!"]
];
var FMT=load("format",{text:"*Bold* _italic_ ~strike~ ```monospace```\n\nType your message here.",vals:{}});
function waFormat(s){
  var h=esc(s);
  h=h.replace(/```([\s\S]+?)```/g,function(m,a){return "<code>"+a+"</code>";});
  h=h.replace(/(^|[\s(])\*(?!\s)([^*\n]+?)(?<!\s)\*(?=$|[\s).,!?:;])/gm,"$1<b>$2</b>");
  h=h.replace(/(^|[\s(])_(?!\s)([^_\n]+?)(?<!\s)_(?=$|[\s).,!?:;])/gm,"$1<i>$2</i>");
  h=h.replace(/(^|[\s(])~(?!\s)([^~\n]+?)(?<!\s)~(?=$|[\s).,!?:;])/gm,"$1<s>$2</s>");
  return h;
}
function phs(s){var o=[],m,re=/\{(\w+)\}/g;while((m=re.exec(s)))if(o.indexOf(m[1])<0)o.push(m[1]);return o;}
function fmtOut(){return FMT.text.replace(/\{(\w+)\}/g,function(m,k){var v=FMT.vals[k];return v?v:m;});}
VIEWS.format={html:function(){
  return '<div class="head"><h1>Message formatter</h1><p class="muted">Style a message the way WhatsApp shows it, or start from a ready business message and fill in the blanks.</p></div>'+
  '<div class="tool"><div class="stack"><div class="card"><label class="f">Start from a template<select id="f-tpl"><option value="">Choose a template</option>'+TEMPLATES.map(function(t,i){return '<option value="'+i+'">'+esc(t[0])+'</option>';}).join("")+'</select></label>'+
    '<div class="toolbar" role="group" aria-label="Formatting"><button data-wrap="*" title="Bold"><b>B</b></button><button data-wrap="_" title="Italic"><i>I</i></button><button data-wrap="~" title="Strikethrough"><s>S</s></button><button data-wrap="```" title="Monospace" style="font-family:var(--mono)">M</button></div>'+
    '<label class="f">Message<textarea id="f-text" style="min-height:180px">'+esc(FMT.text)+'</textarea></label><div class="small muted" id="f-count"></div></div>'+
    '<div class="card" id="f-fillcard"><h2>Fill in the blanks</h2><div id="f-fill" class="grid2"></div></div></div>'+
  '<div class="sticky"><div class="card"><h2>How it looks in WhatsApp</h2><div class="phone" style="height:auto;min-height:220px"><div class="msgs"><div class="bub out wa" id="f-prev"></div></div></div>'+
    '<div class="row"><button class="btn" id="f-copy">Copy message</button><a class="btn ghost" id="f-open" target="_blank" rel="noopener">Send in WhatsApp</a></div></div></div></div>';
},mount:function(){fmtFill();fmtUpdate();}};
function fmtFill(){var p=phs(FMT.text);$("f-fillcard").hidden=!p.length;$("f-fill").innerHTML=p.map(function(k){return '<label class="f">'+esc(k)+'<input id="ff-'+esc(k)+'" data-fv="'+esc(k)+'" type="text" value="'+esc(FMT.vals[k]||"")+'"></label>';}).join("");}
function fmtUpdate(){var o=fmtOut();$("f-prev").innerHTML=waFormat(o)||'<span class="muted">Empty message</span>';$("f-count").textContent=o.length+" characters";$("f-open").href="https://wa.me/?text="+encodeURIComponent(o);store("format",FMT);}

/* ============ BUSINESS CARD ============ */
var CARD=load("card",{first:"Ayesha",last:"Malik",title:"Founder",org:"Malik Interiors",phone:"0300 1234567",work:"",cc:"92",email:"ayesha@example.com",website:"malikinteriors.pk",address:"Gulberg III, Lahore",note:"",color:"#2C55F0"});
VIEWS.card={html:function(){
  var F=[["first","First name","text"],["last","Last name","text"],["title","Job title","text"],["org","Business","text"],["phone","Mobile","tel"],["work","Office phone (optional)","tel"],["email","Email","email"],["website","Website","url"],["address","Address","text"],["cc","Country code","text"]];
  return '<div class="head"><h1>Digital business card</h1><p class="muted">People scan the code and your details go straight into their phone contacts. Print it on your card, counter or flyer, or send the .vcf file on WhatsApp.</p></div>'+
  '<div class="tool"><div class="card"><div class="grid2">'+F.map(function(f){return '<label class="f">'+f[1]+'<input id="c-'+f[0]+'" data-c="'+f[0]+'" type="'+f[2]+'" value="'+esc(CARD[f[0]])+'"></label>';}).join("")+'</div>'+
    '<label class="f">Note (optional)<input id="c-note" data-c="note" type="text" value="'+esc(CARD.note)+'"></label><label class="f">Card colour<input id="c-color" data-c="color" type="color" value="'+esc(CARD.color)+'"></label><div id="c-err"></div></div>'+
  '<div class="sticky stack"><div class="bizcard" id="c-prev"></div><div class="card"><div class="qrwrap"><canvas id="c-qr" width="512" height="512" aria-label="Contact QR code"></canvas>'+
    '<div class="row" style="justify-content:center"><button class="btn" id="c-png">Download QR</button><button class="btn ghost" id="c-vcf">Download .vcf</button><button class="btn ghost" id="c-copy">Copy contact text</button></div></div></div></div></div>';
},mount:function(){cardUpdate();}};
function cardUpdate(){
  var vc=buildVCard(CARD),ok=!!String(CARD.first||CARD.last||CARD.org||"").trim(),ph=normPhone(CARD.phone,CARD.cc);
  var tc=lum(/^#[0-9a-f]{6}$/i.test(CARD.color)?CARD.color:"#2C55F0")>0.45?"#111":"#fff";
  $("c-prev").style.background=CARD.color;$("c-prev").style.color=tc;
  $("c-prev").innerHTML='<div class="nm">'+esc(((CARD.first||"")+" "+(CARD.last||"")).trim()||CARD.org||"Your name")+'</div><div class="ln">'+esc([CARD.title,CARD.org].filter(Boolean).join(" · "))+'</div><div style="flex:1"></div>'+
    (ph?'<div class="ln">+'+esc(ph)+'</div>':'')+(CARD.email?'<div class="ln">'+esc(CARD.email)+'</div>':'')+(CARD.website?'<div class="ln">'+esc(String(CARD.website).replace(/^https?:\/\//,""))+'</div>':'')+(CARD.address?'<div class="ln">'+esc(CARD.address)+'</div>':'');
  $("c-err").innerHTML=ok?(CARD.phone&&!phoneOk(ph)?'<div class="note bad">Check the mobile number.</div>':''):'<div class="note info">Enter a name or business.</div>';
  ["c-png","c-vcf","c-copy"].forEach(function(id){$(id).disabled=!ok;});
  var cv=$("c-qr");if(ok){try{drawQR(cv,vc,{size:512,margin:4,fg:"#111111",bg:"#FFFFFF",style:"square",eye:"square",ecl:"M"});}catch(e){$("c-err").innerHTML='<div class="note bad">'+esc(e.message)+'</div>';}}
  store("card",CARD);return vc;
}

/* ============ events ============ */
function readImage(file,max,cb){
  if(!file||!/^image\//.test(file.type)){toast("Choose an image file, such as PNG or JPG.");return;}
  var fr=new FileReader();fr.onload=function(){var im=new Image();im.onload=function(){var sc=Math.min(1,max/Math.max(im.width,im.height)),c=document.createElement("canvas");c.width=Math.max(1,Math.round(im.width*sc));c.height=Math.max(1,Math.round(im.height*sc));c.getContext("2d").drawImage(im,0,0,c.width,c.height);cb(c.toDataURL("image/png"));};im.onerror=function(){toast("That image could not be opened.");};im.src=fr.result;};fr.readAsDataURL(file);
}
function readJSON(file,cb){var fr=new FileReader();fr.onload=function(){try{var o=JSON.parse(fr.result);cb(o);}catch(e){toast("That file is not a valid settings file.");}};fr.readAsText(file);}
document.addEventListener("input",function(e){
  var t=e.target,d=t.dataset;
  if(current==="qr"){
    if(t.closest("#qr-fields")&&d.k){qrVals()[d.k]=fieldVal(t);if(d.k==="mode"){qrFields();}qrUpdate();return;}
    if(t.id==="qr-fg"){QR.fg=t.value;qrUpdate();return;} if(t.id==="qr-bg"){QR.bg=t.value;qrUpdate();return;}
    if(t.id==="qr-caption"){QR.caption=t.value;qrUpdate();return;} if(t.id==="qr-logoscale"){QR.logoScale=+t.value;qrUpdate();return;}
  }
  if(current==="bot"){
    if(d.b){BOT[d.b]=t.value;botSave();return;} if(d.bh){BOT.hours[d.bh]=t.value;botSave();return;}
    if(d.bo){BOT.options[+d.i][d.bo]=t.value;botSave();return;} if(d.br){BOT.rules[+d.i][d.br]=t.value;botSave();return;}
    if(d.bhand){BOT.handoff[d.bhand]=t.value;botSave();return;} if(d.baway){BOT.away[d.baway]=t.value;botSave();return;}
    if(t.id==="b-apiv"){BOT.apiVersion=t.value.trim()||"v23.0";botSave();$("b-code").textContent=botWorkerCode();return;}
  }
  if(current==="voice"){if(d.v){VOICE[d.v]=t.value;voiceSave();return;} if(d.vf){VOICE.faqs[+d.i][d.vf]=t.value;voiceSave();return;}}
  if(current==="link"&&d.l){LINK[d.l]=t.value;linkUpdate();return;}
  if(current==="widget"&&d.w){WID[d.w]=t.value;widUpdate();return;}
  if(current==="bulk"&&d.bk){BULK[d.bk]=t.value;bulkUpdate();return;}
  if(current==="format"){if(t.id==="f-text"){FMT.text=t.value;var before=phs(FMT.text).join(),shown=Array.prototype.map.call(document.querySelectorAll("[data-fv]"),function(x){return x.dataset.fv;}).join();if(before!==shown)fmtFill();fmtUpdate();return;} if(d.fv){FMT.vals[d.fv]=t.value;fmtUpdate();return;}}
  if(current==="card"&&d.c){CARD[d.c]=t.value;cardUpdate();return;}
});
document.addEventListener("change",function(e){
  var t=e.target,d=t.dataset;
  if(current==="qr"){
    if(t.closest("#qr-fields")&&d.k){qrVals()[d.k]=fieldVal(t);if(d.k==="mode")qrFields();qrUpdate();return;}
    if(t.id==="qr-margin"){QR.margin=+t.value;qrUpdate();return;} if(t.id==="qr-ecl"){QR.ecl=t.value;qrUpdate();return;} if(t.id==="qr-dl"){QR.dl=+t.value;store("qr",QR);return;}
    if(t.id==="qr-logo"&&t.files[0]){readImage(t.files[0],256,function(url){QR.logo=url;var im=new Image();im.onload=function(){qrLogoImg=im;route();};im.src=url;});return;}
  }
  if(current==="bot"){
    if(t.id==="b-tz"){BOT.tz=t.value;botSave();return;}
    if(t.id==="b-away"){BOT.away.enabled=t.checked;botSave();return;}
    if(t.id==="b-import"&&t.files[0]){readJSON(t.files[0],function(o){if(!o||typeof o!=="object"||!Array.isArray(o.options)){toast("That is not a FreeToolBuilder bot file.");return;}BOT=Object.assign(JSON.parse(JSON.stringify(BOT_DEF)),o);botSave();botLeft();toast("Bot opened");});return;}
  }
  if(current==="voice"){
    if(t.id==="v-lang"){VOICE.lang=t.value;voiceSave();return;}
    if(t.id==="v-bookon"){VOICE.bookingOn=t.checked;voiceSave();return;}
    if(t.id==="v-speak"){vSim.speak=t.checked;if(!t.checked)vStopAudio();return;}
    if(t.id==="v-import"&&t.files[0]){readJSON(t.files[0],function(o){if(!o||typeof o!=="object"||!Array.isArray(o.faqs)){toast("That is not a FreeToolBuilder agent file.");return;}VOICE=Object.assign(JSON.parse(JSON.stringify(VOICE_DEF)),o);voiceSave();vLeft();toast("Agent opened");});return;}
  }
  if(current==="widget"&&t.id==="w-showlabel"){WID.showLabel=t.checked;widUpdate();return;}
  if(current==="format"&&t.id==="f-tpl"&&t.value!==""){FMT.text=TEMPLATES[+t.value][1];$("f-text").value=FMT.text;fmtFill();fmtUpdate();t.value="";return;}
});
document.addEventListener("submit",function(e){
  e.preventDefault();
  if(e.target.id==="bot-form"){var i=$("bot-in"),v=i.value.trim();if(!v)return;i.value="";botSend(v);return;}
  if(e.target.id==="v-form"){var j=$("v-in"),w=j.value.trim();if(!w)return;j.value="";vCaller(w);return;}
});
document.addEventListener("click",function(e){
  var t=e.target.closest("button,a[data-copyid]");if(!t)return;var d=t.dataset;
  if(d.copyid){var el=$(d.copyid);if(el)copyText(el.textContent);return;}
  if(d.jump){var jt=$(d.jump);if(jt)jt.scrollIntoView({behavior:"smooth",block:"start"});return;}
  /* QR */
  if(d.qtype){QR.type=d.qtype;document.querySelectorAll("[data-qtype]").forEach(function(b){b.setAttribute("aria-pressed",String(b.dataset.qtype===QR.type));});qrFields();qrUpdate();return;}
  if(d.qstyle){QR.style=d.qstyle;document.querySelectorAll("[data-qstyle]").forEach(function(b){b.setAttribute("aria-pressed",String(b.dataset.qstyle===QR.style));});qrUpdate();return;}
  if(d.qeye){QR.eye=d.qeye;document.querySelectorAll("[data-qeye]").forEach(function(b){b.setAttribute("aria-pressed",String(b.dataset.qeye===QR.eye));});qrUpdate();return;}
  switch(t.id){
    case "qr-swap":QR.fg="#111827";QR.bg="#FFFFFF";$("qr-fg").value=QR.fg;$("qr-bg").value=QR.bg;qrUpdate();return;
    case "qr-logo-clear":QR.logo="";qrLogoImg=null;store("qr",QR);route();return;
    case "qr-copy":copyText(qrPayload);return;
    case "qr-png":{var c=document.createElement("canvas");try{drawQR(c,qrPayload,qrOpts(+QR.dl));}catch(x){toast(x.message);return;}c.toBlob(function(b){saveFile(qrFileName("png"),b);},"image/png");return;}
    case "qr-svg":try{saveFile(qrFileName("svg"),qrSVG(qrPayload,qrOpts(1024)),"image/svg+xml");}catch(x){toast(x.message);}return;
    case "l-copy":copyText(linkUpdate(),"Link copied");return;
    case "l-png":$("l-qr").toBlob(function(b){saveFile("whatsapp-link-qr.png",b);},"image/png");return;
    case "l-toqr":return;
    case "w-copy":copyText(widgetSnippet(false),"Code copied");return;
    case "bk-copy":copyText(bulkRows().filter(function(r){return r.ok;}).map(function(r){return (r.name?r.name+": ":"")+r.link;}).join("\n"),"Links copied");return;
    case "bk-csv":saveFile("whatsapp-links.csv","\ufeffName,Number,Link\r\n"+bulkRows().filter(function(r){return r.ok;}).map(function(r){return [csvCell(r.name),csvCell("+"+r.num),csvCell(r.link)].join(",");}).join("\r\n"),"text/csv;charset=utf-8");return;
    case "f-copy":copyText(fmtOut(),"Message copied");return;
    case "c-png":$("c-qr").toBlob(function(b){saveFile("contact-qr.png",b);},"image/png");return;
    case "c-vcf":saveFile(((CARD.first||"")+"-"+(CARD.last||"")).replace(/[^\w-]+/g,"").replace(/^-|-$/g,"")+".vcf"||"contact.vcf",buildVCard(CARD),"text/vcard");return;
    case "c-copy":copyText(buildVCard(CARD),"Contact copied");return;
    /* bot */
    case "b-addopt":BOT.options.push({title:"",reply:""});botSave();botLeft();var n=$("bo-t-"+(BOT.options.length-1));if(n)n.focus();return;
    case "b-addrule":BOT.rules.push({keywords:"",reply:""});botSave();botLeft();var m=$("br-k-"+(BOT.rules.length-1));if(m)m.focus();return;
    case "b-export":saveFile("whatsapp-bot.json",JSON.stringify(BOT,null,2),"application/json");return;
    case "b-reset":if(t.dataset.confirm){BOT=JSON.parse(JSON.stringify(BOT_DEF));botSave();botLeft();toast("Example bot restored");}else{t.dataset.confirm="1";t.textContent="Click again to replace your bot";setTimeout(function(){if(t.isConnected){delete t.dataset.confirm;t.textContent="Start from the example";}},4000);}return;
    case "bot-clear":botSim.log=[];botRenderMsgs();return;
    case "b-copycode":copyText(botWorkerCode(),"Bot code copied");return;
    case "b-dlcode":saveFile("whatsapp-bot.js",botWorkerCode(),"text/javascript");return;
    /* voice */
    case "v-start":vStart();return;
    case "v-mic":vMicClick();return;
    case "v-addfaq":VOICE.faqs.push({keywords:"",answer:""});voiceSave();vLeft();var q=$("vf-k-"+(VOICE.faqs.length-1));if(q)q.focus();return;
    case "v-export":saveFile("voice-agent.json",JSON.stringify(VOICE,null,2),"application/json");return;
    case "v-reset":if(t.dataset.confirm){VOICE=JSON.parse(JSON.stringify(VOICE_DEF));voiceSave();vLeft();toast("Example agent restored");}else{t.dataset.confirm="1";t.textContent="Click again to replace your agent";setTimeout(function(){if(t.isConnected){delete t.dataset.confirm;t.textContent="Start from the example";}},4000);}return;
    case "v-dlprompt":saveFile("voice-agent-prompt.txt",vPrompt(),"text/plain");return;
    case "v-dljson":saveFile("voice-agent-settings.json",$("v-o-json").textContent,"application/json");return;
  }
  if(d.btab){botTab=d.btab;document.querySelectorAll("[data-btab]").forEach(function(b){b.setAttribute("aria-pressed",String(b.dataset.btab===botTab));});botLeft();return;}
  if(d.bsim){botSim.mode=d.bsim;document.querySelectorAll("[data-bsim]").forEach(function(b){b.setAttribute("aria-pressed",String(b.dataset.bsim===botSim.mode));});botSim.log.push({who:"sys",text:"Testing as: "+(d.bsim==="auto"?"real time":d.bsim)});botRenderMsgs();return;}
  if(d.bday!=null){var day=+d.bday,ds=BOT.hours.days,ix=ds.indexOf(day);if(ix>=0)ds.splice(ix,1);else ds.push(day);ds.sort();botSave();t.className="btn sm "+(ix>=0?"ghost":"soft");t.setAttribute("aria-pressed",String(ix<0));return;}
  if(d.bodel!=null){BOT.options.splice(+d.bodel,1);botSave();botLeft();return;}
  if(d.brdel!=null){BOT.rules.splice(+d.brdel,1);botSave();botLeft();return;}
  if(d.vtab){voiceTab=d.vtab;document.querySelectorAll("[data-vtab]").forEach(function(b){b.setAttribute("aria-pressed",String(b.dataset.vtab===voiceTab));});vLeft();return;}
  if(d.vfdel!=null){VOICE.faqs.splice(+d.vfdel,1);voiceSave();vLeft();return;}
  if(d.wside){WID.side=d.wside;document.querySelectorAll("[data-wside]").forEach(function(b){b.setAttribute("aria-pressed",String(b.dataset.wside===WID.side));});widUpdate();return;}
  if(d.wrap){var ta=$("f-text"),s=ta.selectionStart,en=ta.selectionEnd,w=d.wrap,sel=ta.value.slice(s,en)||"text";ta.value=ta.value.slice(0,s)+w+sel+w+ta.value.slice(en);ta.focus();ta.setSelectionRange(s+w.length,s+w.length+sel.length);FMT.text=ta.value;fmtFill();fmtUpdate();return;}
});
