CD.CATS=[{id:"make",name:"Find or build a tool",about:"Search hundreds of ready tools, or make your own in a minute."},{id:"fun",name:"Cards and greetings",about:"Moving greeting cards and posts to send to people."},{id:"ai",name:"AI tools",about:"Free AI that runs on your own device. No uploads, no account, no limits."},{id:"pdf",name:"PDF tools",about:"Merge, split, compress, sign and convert PDFs without uploading them."},{id:"photo",name:"Photo tools",about:"Passport photos, privacy clean-up and batch conversion."},{id:"world",name:"Work abroad",about:"Time zones, scanned papers and forms for working, studying and travelling across countries."},{id:"media",name:"Video and audio",about:"Record your screen and turn speech into text."},{id:"sell",name:"Selling",about:"Invoices, labels, prices and giveaways."},{id:"daily",name:"Money tools",about:"Pakistan salary tax, zakat, loan instalments and cheque amounts."},{id:"qr",name:"QR and codes",about:"Make, read and print QR codes and barcodes."},{id:"wa",name:"WhatsApp",about:"Links, buttons, bots and messages for WhatsApp."},{id:"voice",name:"Voice and calls",about:"Phone greetings and voice agents."},{id:"content",name:"Content",about:"Status posts, images and text for social media."},{id:"web",name:"Website",about:"Link pages, previews, FAQs and email signatures."}];
var CORE_CAT={qr:"qr",card:"qr",bot:"wa",link:"wa",widget:"wa",bulk:"wa",format:"wa",voice:"voice"};
CD.TOOLS.forEach(function(t){t.cat=CORE_CAT[t.id];});
CD.POPULAR={videofx:1,cards:1,library:1,builder:1,docscan:1,meetplan:1,bgremove:1,transcribe:1,pdfedit:1,pdfcompress:1,passport:1,ocr:1,invoicepro:1,phototext:1,salarytax:1};
