function update(){var r=CD.split(S.total,S.people,S.tip,S.round);
  $("sp-out").innerHTML=big("Each person pays","Rs "+money(r.each),plural(r.people,"person")+" sharing Rs "+money(r.all))+'<div class="stats">'+stat("Rs "+money(r.tip),"tip")+stat("Rs "+money(Math.max(0,r.extra)),"left over after rounding")+'</div><div class="row"><button class="btn" data-act="copy">Copy for WhatsApp group</button></div>';}
