/* EXIF orientation of a JPEG (1 when missing) */
CD.jpegOrientation=function(buf){var v=new DataView(buf);if(v.byteLength<4||v.getUint16(0)!==0xFFD8)return 0;var o=2;
  while(o+4<v.byteLength){var mk=v.getUint16(o);if((mk&0xFF00)!==0xFF00)return 1;var len=v.getUint16(o+2);
    if(mk===0xFFE1&&v.getUint32(o+4)===0x45786966){var t=o+10,le=v.getUint16(t)===0x4949,ifd=t+v.getUint32(t+4,le),n=v.getUint16(ifd,le);for(var i=0;i<n;i++){var e=ifd+2+i*12;if(v.getUint16(e,le)===0x0112)return v.getUint16(e+8,le);}return 1;}
    if(mk===0xFFDA)return 1;o+=2+len;}return 1;};
