function loadImage(f){return new Promise(function(res,rej){var u=URL.createObjectURL(f),im=new Image();im.onload=function(){res({f:f,url:u,im:im,w:im.naturalWidth,h:im.naturalHeight});};im.onerror=function(){URL.revokeObjectURL(u);rej(new Error("image"));};im.src=u;});}
