  var rows=S.list.map(function(city,i){var off=CD.tzOffset(hours[12].t,city[1]),p0=hours[0].cells[i];
    return '<div class="mp-row"><div class="mp-city"><div class="row" style="gap:6px;flex-wrap:nowrap"><b>'+esc(city[0])+'</b>'+(i?'<button class="iconbtn sm" data-act="rm" data-i="'+i+'" aria-label="Remove '+esc(city[0])+'">×</button>':'')+'</div><span class="small muted">'+CD.offsetLabel(off)+' · '+esc(dayLabel(p0))+'</span></div><div class="mp-hours">'+
      hours.map(function(h,j){var p=h.cells[i],nd=j===0||p.d!==hours[j-1].cells[i].d;return '<button class="mp-h '+cls(p)+(j===S.pick?" on":"")+(h.score===best&&best>0?" best":"")+(nd&&j?" nd":"")+'" data-act="pick" data-j="'+j+'" title="'+esc(city[0]+": "+dayLabel(p)+", "+tlabel(p))+'">'+(nd&&j?'<i>'+p.wd+'</i>':'')+tlabel(p,true)+'</button>';}).join("")+'</div></div>';}).join("");
