    '<div class="note '+(best===n?"good":"")+'">'+(best===n?"Everyone is in working hours at ":"Best overlap ("+best+" of "+n+" places in working hours): ")+bestH.map(function(h){return '<b>'+tlabel(h.cells[0])+'</b>';}).join(", ")+' <span class="muted">('+esc(S.list[0][0])+')</span></div>';
  var h=hours[S.pick];
  $("mp-sel").innerHTML=h?'<h2>Meeting time</h2><div>'+S.list.map(function(c,i){var p=h.cells[i];return '<div class="kv"><span>'+esc(c[0])+'</span><b>'+esc(dayLabel(p))+', '+tlabel(p)+' <span class="mp-dot '+cls(p)+'"></span></b></div>';}).join("")+'</div><pre class="out" id="mp-text" style="white-space:pre-wrap">'+esc(inviteText(h))+'</pre><div class="row"><button class="btn" data-copyid="mp-text">Copy invite</button><button class="btn ghost" data-act="ics">Add to calendar (.ics)</button><a class="btn ghost" target="_blank" rel="noopener" href="'+esc(gcal(h))+'">Google Calendar</a></div>':'<div class="small muted">Tap an hour in the grid to pick the meeting time.</div>';
