  var sw=Math.max(8,Math.round(W/24)),shh=Math.max(8,Math.round(H/24)),sm=document.createElement("canvas");sm.width=sw;sm.height=shh;var sx=sm.getContext("2d");sx.imageSmoothingQuality="high";sx.drawImage(cv,0,0,sw,shh);
