  var W=cv.width,H=cv.height,inset=[[W*0.03,H*0.03],[W*0.97,H*0.03],[W*0.97,H*0.97],[W*0.03,H*0.97]];if(bestN<tot*0.15||bestN>tot*0.97)return inset;
