  for(var i=0;i<imgs.length;i++){try{var r=await CD.imgFromFile(imgs[i]),k=Math.min(1,3000/Math.max(r.w,r.h)),pg={id:++seq,name:imgs[i].name,im:r.im,w:Math.round(r.w*k),h:Math.round(r.h*k),rot:0};pg.src=srcCanvas(pg);pg.q=CD.findPage(pg.src);pg.auto=pg.q.map(function(p){return p.slice();});pages.push(pg);}catch(e){toast("Could not open "+imgs[i].name);}}
