function slug(s){return s.toLowerCase().normalize("NFKD").replace(/[̀-ͯ]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"");}
function cap(s){return s.charAt(0).toUpperCase()+s.slice(1);}
function parseCalc(c){
  var ins=c[3].split(";").map(function(p){var a=p.split(":"),o={v:a[0],l:a[1],t:"num",d:a[2]||""};if(a[3]==="date"){o.t="date";}else if(a[2]&&a[2].indexOf("=")>0&&isNaN(a[2])){o.t="sel";o.o=a.slice(2).join(":").split(",").map(function(x){var i=x.indexOf("=");return [x.slice(0,i),x.slice(i+1)];});o.d=o.o[0][0];}return o;});
  var outs=c[4].split(";").map(function(p){var i=p.indexOf("="),l=p.slice(0,i),f=p.slice(i+1),m=/\{(\w+)\}$/.exec(f),o={l:l,f:f};if(m){o.f=f.slice(0,m.index);if(m[1]==="date"||m[1]==="dur")o.fmt=m[1];else o.dp=m[1];}return o;});
  return {k:"calc",n:c[1],d:"",i:ins,o:outs};}
var LIB=null,BYID=null;
