  C.forEach(function(c){if(own(STARTS,c[0]))cur=STARTS[c[0]];add("c-"+c[0],c[1],c[2]+" calculator","calc",function(){return parseCalc(c);},cur);});
  var DEV={b64e:1,b64d:1,urle:1,urld:1,htmle:1,htmld:1,striphtml:1,hexe:1,hexd:1,bine:1,bind:1,jsonf:1,jsonm:1,codes:1,rot13:1};
  Object.keys(TEXT_NAMES).forEach(function(op){add("t-"+op,TEXT_NAMES[op],OPS[op][0]+(op==="count"?" character counter letter count":"")+" text tool","text",function(){var st={op:op};if(op==="replace"){st.a="";st.b="";}return {k:"text",n:TEXT_NAMES[op],d:"",s:[st]};},DEV[op]?"dev":"text");});
  add("t-base","Number base converter","binary bin octal oct decimal dec hexadecimal hex base 2 8 10 16 32 36 number base converter","text",function(){return {k:"text",n:"Number base converter",d:"Binary, octal, decimal, hex or any base from 2 to 36. One number per line.",s:[{op:"base",a:"10",b:"2"}],sample:"255"};},"dev",1);
  Object.keys(U).forEach(function(cat){var list=U[cat][1];add("u-"+cat,U[cat][0]+" converter",U[cat][0]+" converter unit convert "+list.map(function(u){return u[1]+" "+u[0]+" "+u[3];}).join(" "),"conv",function(){return {k:"conv",n:U[cat][0]+" converter",d:"Choose the two units. Every other unit is shown below as well.",cat:cat};},"conv",1);});
  [["temperature","Temperature",TEMP],["fuel","Fuel economy",FUEL]].forEach(function(F){add("u-"+F[0],F[1]+" converter",F[1]+" converter unit convert "+F[2].map(function(u){return u[1]+" "+u[0]+" "+u[4];}).join(" "),"conv",function(){return {k:"conv",n:F[1]+" converter",d:"Choose the two units. Every other unit is shown below as well.",cat:F[0]};},"conv",1);});
