var B=null,lastF=null;
function blank(kind){return kind==="text"?{k:"text",n:"",d:"",s:[{op:"trim"},{op:"dedupe"}]}:{k:"calc",n:"",d:"",i:[{v:"price",l:"Price",t:"num",d:"100",auto:1},{v:"qty",l:"Quantity",t:"num",d:"3",auto:1}],o:[{l:"Total",f:"price * qty",dp:"2"}]};}
function shortName(label,taken){var w=(String(label).toLowerCase().normalize("NFKD").match(/[a-z][a-z0-9]*/g)||[]).filter(function(x){return ["the","of","per","in","a","an","and","to"].indexOf(x)<0;}),b=(w[0]||"x").slice(0,10);if(CD.FN_HELP&&["pi","e","if","and","or","not","min","max","round","date","day","month","year","text","abs","log","ln","sum","avg","mod","pow","exp","sin","cos","tan","today","years"].indexOf(b)>=0)b+="1";var n=b,i=2;while(taken.indexOf(n)>=0)n=b+(i++);return n;}
