var sm0=CD.smart;CD.smart=function(raw){var out=(sm0?sm0(raw):[])||[];raw=String(raw||"");if(/[a-z]{2}/i.test(raw)){var pq=parseQ(raw),generic=!out.length||out[0].label==="Count",add=[];if(!generic&&out.length>=5)return out;CD.libSearch(pq.q,{limit:3}).items.forEach(function(e){var row={label:catLabel(e.g),value:e.n,lib:e.id,val:pq.val,q:pq.q};
  if(e.f==="conv"&&pq.val&&isFinite(+pq.val)){try{var cat=e.id.slice(2),pk=CD.convPick(cat,pq.q),us=CD.convUnits(cat);if(pk[0]>=0&&pk[1]>=0){var v=us[pk[1]].from(us[pk[0]].to(+pq.val));row.label=pq.val+" "+us[pk[0]].p+" in "+us[pk[1]].p;row.value=CD.fmtVal(v);row.copy=row.value;}}catch(er){}}add.push(row);});out=generic?add.concat(out):out.concat(add);}return out;};
