 confetti:function(x,W,H,u,t,p){var cols=[p.ac,"#FFFFFF","#FFD166","#EF476F","#06D6A0","#4CC9F0"];for(var i=0;i<80;i++){var sp=1+Math.floor(R(i,1)*3),y=((R(i,2)+t/D*sp)%1)*(H+u*0.1)-u*0.05,xx=R(i,3)*W+Math.sin(t*TAU/D*2+i)*u*0.03;x.save();x.translate(xx,y);x.rotate(t*TAU/D*(1+Math.floor(R(i,4)*4))+i);x.fillStyle=cols[i%cols.length];x.globalAlpha=0.9;x.fillRect(-u*0.011,-u*0.006,u*0.022,u*0.012);x.restore();}},
 balloons:function(x,W,H,u,t,p){var cols=[p.ac,"#FDE047","#60A5FA","#A78BFA","#34D399","#FB923C"];for(var i=0;i<10;i++){var r=u*(0.05+R(i,1)*0.03),y=H+r*2-((R(i,2)+t/D)%1)*(H+r*6),xx=(0.06+R(i,3)*0.88)*W+Math.sin(t*TAU/D+i)*u*0.02;x.globalAlpha=0.9;x.strokeStyle="rgba(255,255,255,.7)";x.lineWidth=u*0.003;x.beginPath();x.moveTo(xx,y+r*1.2);x.quadraticCurveTo(xx+r*0.3,y+r*2,xx,y+r*2.8);x.stroke();x.fillStyle=cols[i%cols.length];x.beginPath();x.ellipse(xx,y,r*0.85,r*1.1,0,0,TAU);x.fill();x.fillStyle="rgba(255,255,255,.45)";x.beginPath();x.ellipse(xx-r*0.3,y-r*0.4,r*0.16,r*0.28,-0.5,0,TAU);x.fill();}x.globalAlpha=1;},
 fireworks:function(x,W,H,u,t,p){var cols=[p.ac,"#FFFFFF","#F472B6","#60A5FA","#34D399"];for(var k=0;k<6;k++){var age=(t-R(k,1)*D+D)%D,life=1.9;if(age>life)continue;var q=age/life,cx=(0.15+R(k,2)*0.7)*W,cy=(0.12+R(k,3)*0.45)*H,rad=u*(0.16+R(k,4)*0.14)*ease(q);x.fillStyle=cols[k%cols.length];for(var i=0;i<30;i++){var a=i*TAU/30+k,px=cx+Math.cos(a)*rad,py=cy+Math.sin(a)*rad+u*0.06*q*q;x.globalAlpha=(1-q)*(0.6+0.4*R(i,k));x.beginPath();x.arc(px,py,u*0.006*(1-q*0.5),0,TAU);x.fill();}}x.globalAlpha=1;},
 hearts:function(x,W,H,u,t,p){for(var i=0;i<18;i++){var q=(R(i,1)+t/D)%1,s=u*(0.02+R(i,2)*0.035),y=H+s-q*(H+s*4),xx=R(i,3)*W+Math.sin(t*TAU/D*2+i)*u*0.025;x.globalAlpha=0.25+0.55*Math.sin(q*Math.PI);x.fillStyle=i%3?p.ac:"#FFFFFF";heart(x,xx,y,s);}x.globalAlpha=1;},
 stars:function(x,W,H,u,t,p){for(var i=0;i<70;i++){var a=0.15+0.85*Math.abs(Math.sin(t*TAU/D*(1+i%3)/2+R(i,1)*TAU));x.globalAlpha=a;x.fillStyle=i%4?p.ac:"#FFFFFF";star4(x,R(i,2)*W,R(i,3)*H,u*(0.004+R(i,4)*0.012));}x.globalAlpha=1;},
 snow:function(x,W,H,u,t){x.fillStyle="#FFFFFF";for(var i=0;i<90;i++){var sp=1+Math.floor(R(i,1)*2),y=((R(i,2)+t/D*sp)%1)*(H+20)-10,xx=R(i,3)*W+Math.sin(t*TAU/D+i)*u*0.03;x.globalAlpha=0.35+R(i,4)*0.6;x.beginPath();x.arc(xx,y,u*(0.003+R(i,5)*0.007),0,TAU);x.fill();}x.globalAlpha=1;},
 moon:function(x,W,H,u,t,p){FX.stars(x,W,H,u,t,{ac:"#FFFFFF"});var mx=W*0.78,my=H*0.17,mr=u*0.1;x.save();x.shadowColor=p.ac;x.shadowBlur=u*0.05;x.fillStyle=p.ac;x.beginPath();x.arc(mx,my,mr,0.35*Math.PI,1.65*Math.PI,false);x.arc(mx+mr*0.42,my,mr*0.82,1.72*Math.PI,0.28*Math.PI,true);x.closePath();x.fill();x.restore();
   for(var i=0;i<3;i++){var lx=W*(0.14+i*0.13),len=H*(0.1+0.05*((i+1)%3)),sw=Math.sin(t*TAU/D+i*1.3)*0.09,ex=lx+Math.sin(sw)*len,ey=Math.cos(sw)*len,lw=u*0.045,lh=u*0.075;x.strokeStyle=p.ac;x.lineWidth=u*0.003;x.beginPath();x.moveTo(lx,0);x.lineTo(ex,ey);x.stroke();x.save();x.translate(ex,ey);x.rotate(-sw);x.shadowColor="#FFD166";x.shadowBlur=u*0.04;x.fillStyle=p.ac;x.beginPath();x.moveTo(-lw*0.3,0);x.lineTo(lw*0.3,0);x.lineTo(lw*0.5,lh*0.25);x.lineTo(lw*0.5,lh*0.8);x.lineTo(0,lh);x.lineTo(-lw*0.5,lh*0.8);x.lineTo(-lw*0.5,lh*0.25);x.closePath();x.fill();x.fillStyle="rgba(255,244,200,"+(0.6+0.3*Math.sin(t*TAU/D*3+i))+")";x.fillRect(-lw*0.25,lh*0.3,lw*0.5,lh*0.42);x.restore();}},
 petals:function(x,W,H,u,t,p){for(var i=0;i<42;i++){var sp=1+Math.floor(R(i,1)*2),y=((R(i,2)+t/D*sp)%1)*(H+u*0.1)-u*0.05,xx=R(i,3)*W+Math.sin(t*TAU/D*2+i)*u*0.05;x.save();x.translate(xx,y);x.rotate(t*TAU/D*(1+i%2)+i);x.globalAlpha=0.55+R(i,4)*0.35;x.fillStyle=i%3?p.ac:"#FFFFFF";x.beginPath();x.ellipse(0,0,u*0.02,u*0.01,0,0,TAU);x.fill();x.restore();}},
