 ,emoji:function(x,W,H,u,t,p){var em=Array.from(p.em||"✨");x.textAlign="center";x.textBaseline="middle";for(var i=0;i<20;i++){var q=(R(i,1)+t/D)%1,s=u*(0.05+R(i,2)*0.05),y=H+s-q*(H+s*3),xx=R(i,3)*W+Math.sin(t*TAU/D*2+i)*u*0.03;x.save();x.translate(xx,y);x.rotate(Math.sin(t*TAU/D*2+i*2)*0.25);x.globalAlpha=0.35+0.6*Math.sin(q*Math.PI);x.font=Math.round(s)+"px 'Apple Color Emoji','Segoe UI Emoji','Noto Color Emoji',sans-serif";x.fillStyle=p.ac;x.fillText(em[i%em.length],0,0);x.restore();}},
