 bunting:function(x,W,H,u,t,p){var cols=[p.ac,"#FDE047","#34D399","#60A5FA","#F472B6","#FB923C"];for(var row=0;row<2;row++){var n=11,sag=u*(0.07+row*0.05),y0=H*(0.03+row*0.07);x.strokeStyle="rgba(0,0,0,.25)";x.lineWidth=u*0.003;x.beginPath();for(var i=0;i<=n;i++){var q=i/n,px=q*W,py=y0+Math.sin(q*Math.PI)*sag;if(i)x.lineTo(px,py);else x.moveTo(px,py);}x.stroke();for(i=0;i<n;i++){var q2=(i+0.5)/n,cx=q2*W,cy=y0+Math.sin(q2*Math.PI)*sag,sw=Math.sin(t*TAU/D*2+i+row)*0.16,s=u*0.035;x.save();x.translate(cx,cy);x.rotate(sw);x.fillStyle=cols[(i+row*2)%cols.length];x.globalAlpha=0.95;x.beginPath();x.moveTo(-s,0);x.lineTo(s,0);x.lineTo(0,s*1.9);x.closePath();x.fill();x.restore();}}x.globalAlpha=0.5;FX.confetti(x,W,H,u,t,p);x.globalAlpha=1;},
