 beams:function(x,W,H,u,t,p){var cols=[p.ac,"#22D3EE","#F472B6","#FDE047","#A78BFA","#34D399"],L=Math.hypot(W,H);x.save();x.globalCompositeOperation="lighter";for(var i=0;i<6;i++){var a=Math.PI/2+Math.sin(t*TAU/D*(1+i%2)+i*1.1)*0.75,g=x.createLinearGradient(W/2,0,W/2+Math.cos(a)*L,Math.sin(a)*L);g.addColorStop(0,cols[i]);g.addColorStop(1,"rgba(0,0,0,0)");x.globalAlpha=0.22;x.fillStyle=g;x.beginPath();x.moveTo(W/2,-u*0.02);x.lineTo(W/2+Math.cos(a-0.09)*L,Math.sin(a-0.09)*L);x.lineTo(W/2+Math.cos(a+0.09)*L,Math.sin(a+0.09)*L);x.closePath();x.fill();}x.restore();FX.dust(x,W,H,u,t,{ac:"#FFFFFF"});},
