 kites:function(x,W,H,u,t,p){var cols=[p.ac,"#EF4444","#FDE047","#FFFFFF","#F97316","#A855F7"];for(var i=0;i<8;i++){var s=u*(0.035+R(i,1)*0.03),cx=(0.08+R(i,2)*0.84)*W+Math.sin(t*TAU/D+i*1.7)*u*0.04,cy=(0.06+R(i,3)*0.5)*H+Math.cos(t*TAU/D*2+i)*u*0.02,rot=Math.sin(t*TAU/D*2+i)*0.25;x.save();x.translate(cx,cy);x.rotate(rot);x.globalAlpha=0.95;x.fillStyle=cols[i%cols.length];x.beginPath();x.moveTo(0,-s*1.2);x.lineTo(s*0.8,0);x.lineTo(0,s*1.4);x.lineTo(-s*0.8,0);x.closePath();x.fill();x.strokeStyle="rgba(0,0,0,.3)";x.lineWidth=u*0.002;x.beginPath();x.moveTo(0,-s*1.2);x.lineTo(0,s*1.4);x.moveTo(-s*0.8,0);x.lineTo(s*0.8,0);x.stroke();x.beginPath();x.moveTo(0,s*1.4);for(var k=1;k<=6;k++)x.lineTo(Math.sin(t*TAU/D*2+k+i)*s*0.4,s*1.4+k*s*0.5);x.stroke();x.restore();}x.globalAlpha=1;},
