/* ---------- trending reel effects: fn(a, W, H, t, st) works on the finished work canvas ---------- */
function small(st,w,h){if(!st.sm||st.sm.width!==w||st.sm.height!==h){st.sm=mk(w,h);}var x=st.sm.getContext("2d");x.filter="none";x.globalAlpha=1;x.globalCompositeOperation="source-over";x.drawImage(st.c0,0,0,w,h);return x.getImageData(0,0,w,h);}
function hist(st,keep,W,H){st.hs=st.hs||[];var c=st.hs.length>=keep?st.hs.shift():mk(Math.round(W/2),Math.round(H/2));c.getContext("2d").drawImage(st.c0,0,0,c.width,c.height);st.hs.push(c);return st.hs;}
function copy(st,W,H){if(!st.cp||st.cp.width!==W){st.cp=mk(W,H);}var x=st.cp.getContext("2d");x.globalCompositeOperation="source-over";x.globalAlpha=1;x.drawImage(st.c0,0,0);return st.cp;}
function beat(t,bpm){var q=(t*(bpm||120)/60)%1;return q;}
