function loop(){cancelAnimationFrame(raf);var cv=$("vf-cv");if(!cv||!v||!v.videoWidth)return;var x=cv.getContext("2d");(function f(){if(!document.contains(cv)||!v)return;var lim=limit();st.pr=lim?Math.min(1,v.currentTime/lim):0;if(!busy&&lim&&v.currentTime>=lim-0.03&&!v.paused){v.currentTime=0;}CD.vfxDraw(x,cv.width,cv.height,v,v.currentTime,sel(),st);var b=$("vf-time");if(b)b.textContent=v.currentTime.toFixed(1)+" / "+(lim||0).toFixed(1)+" s";raf=requestAnimationFrame(f);})();}
