/* Turns the CV into a picture (canvas) by drawing the page through an SVG. Returns {canvas, pages}. */
CD.cvCanvas=function(id,d,scale){return new Promise(function(res,rej){var r=CD.cvHTML(id,d,{inner:true}),probe=document.createElement("div");probe.style.cssText="position:fixed;left:-9999px;top:0;width:"+W+"px";probe.innerHTML='<style>'+r.css+'</style>'+r.page;document.body.appendChild(probe);var full=Math.max(H,Math.ceil(probe.querySelector(".cv").getBoundingClientRect().height));
  var pages=Math.ceil((full-4)/H),ht=pages*H;document.body.removeChild(probe);
  var xhtml='<div xmlns="http://www.w3.org/1999/xhtml"><style>'+r.css+'.cv{min-height:'+ht+'px}</style>'+r.page+'</div>';
  xhtml=new XMLSerializer().serializeToString(new DOMParser().parseFromString('<div xmlns="http://www.w3.org/1999/xhtml">'+'<style>'+r.css.replace(/</g,"&lt;")+'.cv{min-height:'+ht+'px}</style>'+r.page+'</div>',"text/html").body.firstChild);
  var svg='<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+ht+'"><foreignObject width="100%" height="100%">'+xhtml+'</foreignObject></svg>',img=new Image();
  img.onload=function(){try{var c=document.createElement("canvas");c.width=W*scale;c.height=ht*scale;var x=c.getContext("2d");x.fillStyle="#fff";x.fillRect(0,0,c.width,c.height);x.scale(scale,scale);x.drawImage(img,0,0);c.toDataURL("image/png").length;res({canvas:c,pages:pages});}catch(e){rej(e);}};img.onerror=function(){rej(new Error("render"));};
  img.src="data:image/svg+xml;charset=utf-8,"+encodeURIComponent(svg);});};
CD.cvText=function(d){var o=[String(d.name||"").toUpperCase(),d.title,[d.email,d.phone,d.loc,d.web].filter(function(x){return String(x||"").trim();}).join(" | "),""];
  if(String(d.summary||"").trim())o.push("PROFILE",d.summary,"");var ex=(d.exp||[]).filter(function(e){return e.r||e.c;});if(ex.length){o.push("EXPERIENCE");ex.forEach(function(e){o.push(e.r+(e.c?", "+e.c:"")+(e.d?" ("+e.d+")":""));linesOf(e.b).forEach(function(b){o.push("- "+b);});o.push("");});}
  var ed=(d.edu||[]).filter(function(e){return e.q||e.s;});if(ed.length){o.push("EDUCATION");ed.forEach(function(e){o.push(e.q+(e.s?", "+e.s:"")+(e.d?" ("+e.d+")":""));});o.push("");}
  if(list(d.skills).length)o.push("SKILLS",list(d.skills).map(function(x){return skillParse(x).n;}).join(", "),"");if(list(d.langs).length)o.push("LANGUAGES",list(d.langs).join(", "),"");if(linesOf(d.certs).length)o.push("CERTIFICATES"),linesOf(d.certs).forEach(function(c){o.push("- "+c);}),o.push("");if(linesOf(d.extra).length)o.push("MORE"),linesOf(d.extra).forEach(function(c){o.push("- "+c);});
  return o.filter(function(x){return x!=null;}).join("\n").replace(/\n{3,}/g,"\n\n").trim()+"\n";};
