(function(){var CD=window.CD,R={};CD.RETIRED.forEach(function(id){R[id]=1;});for(var i=CD.TOOLS.length-1;i>=0;i--)if(R[CD.TOOLS[i].id])CD.TOOLS.splice(i,1);})();
window.CD.route();

